    }, PREVIEW_DEBOUNCE_MS);

    return () => window.clearTimeout(timeoutId);
  }, [getValue]);

  return <div className=\"yfm\" dangerouslySetInnerHTML={{__html: html}} />;
}

export function App() {
  const themeValue = useThemeValue();
  const renderPreview = useCallback(
